<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$rows=$pdo->query("SELECT l.id,u.name,c.code,b.title,l.loan_date,l.due_date,l.returned_at,l.late_days,l.fine FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id ORDER BY l.loan_date DESC,l.id DESC")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Riwayat Transaksi</title><link rel=stylesheet href=../public/style.css></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>☷ Riwayat Transaksi</h1><div class=card><b>Total transaksi: <?=count($rows)?></b></div><br><table class=table><tr><th>Anggota</th><th>Buku</th><th>Pinjam</th><th>Jatuh Tempo</th><th>Kembali</th><th>Status</th><th>Denda</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['code'].' - '.$r['title'])?></td><td><?=$r['loan_date']?></td><td><?=$r['due_date']?></td><td><?=$r['returned_at']?:'-'?></td><td><?=$r['returned_at']?'🟢 Selesai':($r['due_date']<date('Y-m-d')?'🔴 Terlambat':'🟡 Aktif')?></td><td>Rp <?=number_format($r['fine'],0,',','.')?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan=7>Belum ada transaksi.</td></tr><?php endif?></table></main></div></body></html>